class Solution {
    public boolean escapeGhosts(int[][] ghosts,int[] target){
        int player=Math.abs(target[0])+Math.abs(target[1]);
        for(int[] ghost:ghosts)if(Math.abs(ghost[0]-target[0])+Math.abs(ghost[1]-target[1])<=player)return false;
        return true;
    }
}

